<?php require 'config.php'; role(['admin']); if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM menus WHERE id=$id");header('Location:menus.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$cat=(int)$_POST['category_id'];$name=trim($_POST['name']);$price=(int)$_POST['price'];$stock=(int)$_POST['stock'];if($id){$s=$conn->prepare("UPDATE menus SET category_id=?,name=?,price=?,stock=? WHERE id=?");$s->bind_param('isiii',$cat,$name,$price,$stock,$id);}else{$s=$conn->prepare("INSERT INTO menus(category_id,name,price,stock) VALUES(?,?,?,?)");$s->bind_param('isii',$cat,$name,$price,$stock);} $s->execute();header('Location:menus.php');exit;}$edit=null;if(isset($_GET['edit'])){$edit=$conn->query("SELECT * FROM menus WHERE id=".(int)$_GET['edit'])->fetch_assoc();}$cats=$conn->query("SELECT * FROM categories ORDER BY name");$menus=$conn->query("SELECT m.*,c.name category FROM menus m JOIN categories c ON c.id=m.category_id ORDER BY m.id DESC");include 'partials/header.php';?><div class="mb-3"><div class="section-title">Data Menu</div><div class="sub">Kelola nama menu, kategori, harga, dan stok.</div></div><div class="row g-3"><div class="col-lg-4"><div class="cardx p-3"><h5><?=$edit?'Edit':'Tambah'?> Menu</h5><div class="sub mb-3">Isi data menu restoran.</div><form method="post"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><select name="category_id" class="form-select mb-2" required><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=isset($edit)&&$edit['category_id']==$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endwhile;?></select><input name="name" class="form-control mb-2" placeholder="Nama menu" value="<?=htmlspecialchars($edit['name']??'')?>" required><input name="price" type="number" class="form-control mb-2" placeholder="Harga" value="<?=$edit['price']??''?>" required><input name="stock" type="number" class="form-control mb-3" placeholder="Stok" value="<?=$edit['stock']??0?>" required><button class="btn btn-primary w-100">Simpan Menu</button><?php if($edit):?><a href="menus.php" class="btn btn-light w-100 mt-2">Batal</a><?php endif;?></form></div></div><div class="col-lg-8"><div class="cardx"><div class="card-head"><div><h5>Daftar Menu</h5><small>Data menu restoran</small></div></div><div class="table-responsive p-2"><table class="table mb-0"><thead><tr><th>MENU</th><th>KATEGORI</th><th>HARGA</th><th>STOK</th><th>AKSI</th></tr></thead><tbody><?php while($m=$menus->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($m['name'])?></b></td><td><?=$m['category']?></td><td><?=rupiah($m['price'])?></td><td><span class="badge-soft"><?=$m['stock']?></span></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$m['id']?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" href="?delete=<?=$m['id']?>" onclick="return confirm('Hapus menu?')"><i class="bi bi-trash"></i></a></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php include 'partials/footer.php';?>